    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String owner = sc.next();
        int initial = sc.nextInt();
        int k = sc.nextInt();

        Account account = new Account(owner, initial);

        for (int i = 0; i < k; i++) {
            String command = sc.next();
