import java.util.Scanner;

class Account {
    private final String owner;
    private int balance;

    Account(String owner, int balance) {
        this.owner = owner;
        this.balance = balance;
    }

    String getOwner() {
        return owner;
    }

    int getBalance() {
        return balance;
    }

    boolean deposit(int amount) {
        if (amount <= 0) {
            return false;
        }
        balance += amount;
        return true;
    }

    boolean withdraw(int amount) {
        if (amount <= 0 || amount > balance) {
            return false;
        }
        balance -= amount;
        return true;
    }

    boolean transferTo(Account other, int amount) {
        if (!this.withdraw(amount)) {
            return false;
        }
        other.deposit(amount);
        return true;
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        Account a = new Account(sc.next(), sc.nextInt());
        Account b = new Account(sc.next(), sc.nextInt());
        int k = sc.nextInt();

        for (int i = 0; i < k; i++) {
